#include <iostream>
bool apply(int &value, int delta) {
    if (value + delta < 0 || value + delta > 10) {
        return false;
    }
    value += delta;
    return true;
}
int main() {
    int value = 9;
    bool accepted = apply(value, 2);
    std::cout << accepted << ' ' << value << '\n';
}

